<script setup>
import {ref,reactive,onMounted,watch} from 'vue'
import {api} from '../api.js'
import {prepareScanMaterials,setMaterialColor,restoreMaterialColor} from '../customization.js'
import '../seller.css'
const props=defineProps({mode:{type:String,required:true}}),emit=defineEmits(['changed'])
const reference=ref(null),original=new Map()
const rows=ref([]),error=ref(''),busy=ref(false),loading=ref(false),filter=ref('all'),selected=ref(null),source=ref(null),notes=reactive({}),viewer=ref(null),part=ref(''),photoReviewed=ref(false),testedParts=ref([])
let selection=0
async function load(){loading.value=true;error.value='';try{const result=await api(props.mode==='sellers'?'sellers/list.php':'products/list.php?review=1');rows.value=result.sellers||result.shoes}catch(cause){error.value=cause.message}finally{loading.value=false}}
async function inspect(row){const request=++selection;selected.value=row;source.value=null;reference.value=null;original.clear();part.value=row.parts?.[0]?.material||'';photoReviewed.value=false;testedParts.value=[];if(row.sourceScanId)try{const result=await api('products/scan.php?id='+encodeURIComponent(row.id));if(request===selection){source.value=result.job;reference.value=result.job.images[0]}}catch(cause){if(request===selection)error.value=cause.message}}
async function loaded(){try{await prepareScanMaterials(viewer.value,selected.value.parts);for(const mat of viewer.value.model.materials)original.set(mat.name,[...mat.pbrMetallicRoughness.baseColorFactor])}catch(cause){error.value=cause.message}}
function recolor(value){if(viewer.value?.model&&setMaterialColor(viewer.value.model,part.value,value)&&!testedParts.value.includes(part.value))testedParts.value.push(part.value)}
function reset(){for(const mat of viewer.value?.model?.materials||[]){restoreMaterialColor(viewer.value.model,mat.name);if(original.has(mat.name))mat.pbrMetallicRoughness.setBaseColorFactor(original.get(mat.name))}}
async function review(row,status){error.value='';const note=notes[row.id]??row.reviewNote??'';if(status!=='approved'&&note.trim().length<3){error.value='Explain the decision in the review note.';return}
 if(props.mode==='products'&&status==='approved'&&row.sourceScanId&&(!photoReviewed.value||testedParts.value.length<2)){error.value='Compare source photos and test at least two different parts before approval.';return}
 busy.value=true;try{await api(props.mode==='sellers'?'sellers/review.php':'products/review.php',{method:'POST',body:{id:row.id,status,note,photoReviewed:photoReviewed.value}});selected.value=null;source.value=null;await load();emit('changed')}catch(cause){error.value=cause.message}finally{busy.value=false}}
onMounted(load);watch(()=>props.mode,()=>{selected.value=null;source.value=null;filter.value='all';load()})
</script>
<template>
 <section class="seller" style="padding:0">
  <header><div><h1>{{mode==='sellers'?'Seller applications':'Seller product review'}}</h1><p class="muted">{{mode==='sellers'?'Approve original studios with a clear pickup location. Suspension hides their listings immediately.':'Check the actual model, independent parts, price and pickup store before publishing.'}}</p></div><button :disabled="loading||busy" @click="load">Refresh</button></header>
  <p v-if="error" role="alert" class="error">{{error}}</p><p v-if="loading" role="status">Loading review queue…</p>
  <label style="max-width:240px;margin-bottom:16px">Show<select v-model="filter"><option value="all">All statuses</option><option v-for="status in mode==='sellers'?['pending','approved','rejected','suspended']:['pending','approved','draft','rejected']" :key="status">{{status}}</option></select></label>
  <template v-if="mode==='sellers'">
   <article class="row panel" v-for="row in rows.filter(r=>filter==='all'||r.status===filter)" :key="row.id"><div class="actions"><h2>{{row.storeName}}</h2><strong class="tag">{{row.status}}</strong></div><p>{{row.name}} · {{row.email}}<br>{{row.description}}<br><strong>Pickup:</strong> {{row.pickupAddress}}<br>{{row.contact}}</p><label>Review note<textarea v-model="notes[row.id]" :placeholder="row.reviewNote||'Required for rejection or suspension'" maxlength="1000"></textarea></label><div class="actions"><button class="primary" :disabled="busy" @click="review(row,'approved')">{{row.status==='suspended'?'Restore approval':'Approve seller'}}</button><button :disabled="busy" @click="review(row,'rejected')">Request changes</button><button :disabled="busy" @click="review(row,'suspended')">Suspend seller</button></div></article>
  </template>
  <template v-else>
   <section v-if="selected" class="panel stack" style="margin-bottom:24px"><div class="actions"><h2>{{selected.name}}</h2><button @click="selected=null;source=null;selection++">Close review</button></div><div class="editor-grid"><div><model-viewer :key="selected.id" ref="viewer" :src="selected.glbPath" camera-controls alt="Seller product review model" @load="loaded" @error="error='Could not load product model.'"></model-viewer><label>Test a part<select v-model="part"><option v-for="item in selected.parts" :key="item.id" :value="item.material">{{item.label}}</option></select></label><div class="actions" style="margin-top:12px"><button @click="recolor('#b94d27')">Test rust</button><button @click="recolor('#245fa8')">Test blue</button><button @click="reset">Original texture</button></div><p>{{testedParts.length}} independent parts tested</p></div><div class="stack"><p>{{selected.description}}</p><p>₱{{Number(selected.price).toLocaleString()}} · {{selected.stock}} pairs<br>US sizes: {{selected.sizes.join(', ')}}<br><strong>{{selected.storeName}}</strong><br>{{selected.pickupAddress}}</p><template v-if="selected.sourceScanId"><p v-if="!source">Loading private source capture…</p><template v-else><h3>Original source photographs</h3><p class="muted">Compare toe, sides, heel, sole and photographed detail. Reject unusable geometry, background fragments, or wrong part boundaries.</p><figure v-if="reference"><img :src="reference.previewUrl" :alt="reference.name" style="width:100%;height:300px;object-fit:contain"><figcaption>{{reference.name}}</figcaption></figure><div class="review-images"><button v-for="image in source.images" :key="image.id" type="button" @click="reference=image" :aria-label="'Compare '+image.name"><img :src="image.previewUrl" :alt="image.name" loading="lazy"></button></div><label class="checks"><input type="checkbox" v-model="photoReviewed">I compared all views and this model represents the photographed shoe.</label></template></template><p v-else class="notice">{{selected.glbPath==='/models/shoe-soleview-final.glb'?'This is an original KickCraft template, not a reconstruction of seller photos.':'Uploaded model: verify original design and independently recolorable materials.'}}</p><label>Review note<textarea v-model="notes[selected.id]" :placeholder="selected.reviewNote||'Required when rejecting'" maxlength="1000"></textarea></label><div class="actions"><button v-if="selected.publicationState==='pending'" class="primary" :disabled="busy||(selected.sourceScanId&&(!source||!photoReviewed||testedParts.length<2))" @click="review(selected,'approved')">Approve listing</button><button v-if="['pending','approved'].includes(selected.publicationState)" :disabled="busy" @click="review(selected,'rejected')">Reject listing</button></div></div></div></section>
   <div class="product-list"><article class="panel stack" v-for="row in rows.filter(r=>filter==='all'||r.publicationState===filter)" :key="row.id"><img class="product-image" :src="row.thumbnailPath" :alt="row.name"><p class="tag">{{row.publicationState}}</p><h2>{{row.name}}</h2><p>{{row.storeName}} · {{row.parts.length}} parts</p><p v-if="row.reviewNote">{{row.reviewNote}}</p><button @click="inspect(row)">Inspect listing</button></article></div>
  </template>
  <p v-if="!loading&&!rows.length" class="panel">No {{mode==='sellers'?'seller applications':'seller products'}} yet.</p>
 </section>
</template>
